import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int test_cases = 1;
        for (int i = 0; i < test_cases; i++) {
            perform(br);
        }
    }

    public static void perform(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int total = Integer.parseInt(st.nextToken());
        int limit = Integer.parseInt(st.nextToken());
        double[] probabilities = new double[total];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < total; i++) {
            probabilities[i] = Double.parseDouble(st.nextToken());
        }

        for (int i = 0; i < total; i++) {
            if (Math.abs(probabilities[i]) < 1e-6) {
                System.out.print("0 ");
                continue;
            }
            int subset_len = total - 1;
            int size = 1 << subset_len;
            double[] dp = new double[size];
            List<Double> subset_probs = new ArrayList<>();
            for (int j = 0; j < total; j++) {
                if (j != i) {
                    subset_probs.add(probabilities[j]);
                }
            }
            dp[0] = probabilities[i];
            double total_sum = dp[0];
            for (int mask = 1; mask < size; mask++) {
                double sumP = 0.0, sumVal = 0.0;
                int count = 0;
                for (int t = 0; t < subset_len; t++) {
                    if (((mask >> t) & 1) == 1) {
                        sumP += subset_probs.get(t);
                        sumVal += subset_probs.get(t) * dp[mask ^ (1 << t)];
                        count++;
                    }
                }
                dp[mask] = sumVal / (1 - sumP);
                if (count < limit) {
                    total_sum += dp[mask];
                }
            }
            System.out.print(total_sum + " ");
        }
    }
}
